{
  "extends": "./.tinker/tsconfig.json",
  "include": ["src", "cmds", "tinker", "tests", "vite.config.ts", ".tinker/routeTree.gen.ts"]
}

import { createScope, type Scope } from "@tinker/core";

import { defineMain } from "~/base/main";
import { renderObservation } from "~/base/observe";
import { observeServerPanics } from "~/base/panics.server";
import { createServerHandler, stoppedFetch } from "~/base/server-entry";
import { abortReasons } from "~/components/errors";
import { startRequests, backendStop } from "~/components/requests";
import {
  telemetryExport,
  telemetrySide,
  telemetryService,
  tracesUrl,
  logsUrl,
  logLevel,
  spanHistory,
  consoleOutput,
  observer,
  renderObserve,
  renderNs,
  browserIngest,
  browserTelemetry,
  telemetryWorker,
  threadExport,
  threadObserver,
  threadRenderObserve,
  threadIngest,
} from "~/components/telemetry/index.server";

/** The host starts the server; importing this command opens nothing. */
// oxlint-disable-next-line complexity -- Commands keep env bindings inline. Tests cover input, startup, exit, and close.
export default defineMain(async ({ env, args, signal, stdout, stderr, exit }) => {
  if (args.length) {
    stderr.write("Usage: tinker serve\n");
    exit(64);
    return { fetch: stoppedFetch, closed: Promise.resolve() };
  }
  const stop = { tools: new AbortController(), app: new AbortController() };
  const appStop = AbortSignal.any([signal, stop.app.signal]);
  /** A built server sends telemetry from a worker thread; dev and tests keep it on this thread. */
  const threaded = !import.meta.env.DEV;
  const tools = createScope({
    signal: stop.tools.signal,
    extensions: [threaded ? threadExport : telemetryExport],
    tags: [
      threaded && telemetryWorker(new URL("./telemetry-worker.js", import.meta.url)),
      telemetrySide("server"),
      consoleOutput(stdout),
      env.OTEL_SERVICE_NAME !== undefined && telemetryService(env.OTEL_SERVICE_NAME),
      env.VICTORIA_TRACES_URL !== undefined && tracesUrl(new URL(env.VICTORIA_TRACES_URL)),
      env.VICTORIA_LOGS_URL !== undefined && logsUrl(new URL(env.VICTORIA_LOGS_URL)),
      env.LOG_LEVEL !== undefined && logLevel(Number(env.LOG_LEVEL)),
      env.SPAN_HISTORY !== undefined && spanHistory(Number(env.SPAN_HISTORY)),
    ],
  });

  await tools.ready;

  let closed: Promise<Scope.Result[]> | undefined;

  try {
    const app = createScope({
      signal: appStop,
      observe: tools.resolve(threaded ? threadObserver : observer),
      extensions: [startRequests],
      tags: [
        backendStop(appStop),
        renderObservation(
          threaded
            ? tools.resolve(threadRenderObserve, { ns: renderNs })
            : tools.resolve(renderObserve, { ns: renderNs }),
        ),
        browserTelemetry(tools.resolve(threaded ? threadIngest : browserIngest).ingest),
      ],
    });

    // The host fails the run with the first failure in these results, app first.
    closed = app.closed.then(async function closeRoots(appEnd) {
      stop.tools.abort(abortReasons.closed);
      return [appEnd, await tools.closed];
    });

    await app.ready;
    signal.throwIfAborted(); // Aborted during start: app is closing, so no handler.
    app.onClose(observeServerPanics(exit.bind(null, 1), closed, stderr));
    return {
      fetch: createServerHandler(
        { requestContext: app.resolve(startRequests) },
        { dev: import.meta.env.DEV },
      ).fetch,
      closed,
    };
  } catch (error) {
    // Startup failed: close both roots, then print the first cleanup failure that is not this error.
    stop.app.abort(error);
    stop.tools.abort(error);

    const ended = await (closed ?? tools.closed.then((end) => [end]));

    const cleanup = ended
      .flatMap((end) => [
        ...(end.status === "failed" ? [end.error] : []),
        ...(end.teardownErrors ?? []),
      ])
      .find((failure) => failure !== error);
    if (cleanup !== undefined) stderr.write(`close failed: ${String(cleanup)}\n`);

    throw error;
  }
});

import { createScope } from "@tinker/core";

import {
  createRouterEntry,
  pageEvents,
  readRenderObservation,
  routerScope,
  tabLifetime,
} from "~/base/router-entry";
import { abortReasons } from "~/components/errors";
import {
  telemetryExport,
  telemetrySide,
  telemetryService,
  logConsole,
  observer,
} from "~/components/telemetry";

/** Start asks for a fresh render root; the browser keeps its root until page hide. */
export async function getRouter() {
  const stop = { tools: new AbortController(), app: new AbortController() };
  const tools = import.meta.env.SSR
    ? undefined
    : createScope({
        signal: stop.tools.signal,
        extensions: [telemetryExport],
        tags: [telemetrySide("browser"), telemetryService("tinker-browser"), logConsole(console)],
      });

  try {
    await tools?.ready;
    const app = createScope({
      signal: stop.app.signal,
      extensions: [routerScope],
      observe: tools ? tools.resolve(observer) : readRenderObservation(),
      tags: [pageEvents(import.meta.env.SSR ? undefined : window)],
    });
    const closed = app.closed.then(async (appEnd) => {
      stop.tools.abort(abortReasons.closed);
      const toolsEnd = await tools?.closed;

      for (const result of [appEnd, toolsEnd]) {
        if (result?.status === "failed") throw result.error;
        if (result?.teardownErrors?.length) throw result.teardownErrors[0];
      }
    });
    void closed.catch(() => {});
    const close = () => {
      stop.app.abort(abortReasons.closed);
      return closed;
    };

    return await app.ready
      .then(async () => {
        app.resolve(tabLifetime).bind(close);
        if (import.meta.hot) import.meta.hot.dispose(close);
        return createRouterEntry({
          options: { context: {} },
          Wrap: app.resolve(routerScope),
          close,
          dev: import.meta.env.DEV,
          server: import.meta.env.SSR,
        });
      })
      .catch(async (error) => {
        await close().catch((cleanup) => {
          if (cleanup !== error) console.error(cleanup);
        });
        throw error;
      });
  } catch (error) {
    stop.tools.abort(abortReasons.closed);
    await tools?.closed;
    throw error;
  }
}

import { createScope } from "@tinker/core";

import { serveTelemetryWorker, telemetryWorkerInput } from "~/base/telemetry-worker";
import {
  consoleOutput,
  logsUrl,
  telemetryExport,
  telemetryService,
  telemetrySide,
  threadDrain,
  tracesUrl,
} from "~/components/telemetry/index.server";

/**
 * The telemetry worker thread's root. The server's telemetry root starts it and owns its close.
 * The request side resolved every setting; this command binds them inline.
 */
const { settings, console } = telemetryWorkerInput();

const tools = createScope({
  extensions: [telemetryExport],
  tags: [
    telemetrySide("server"),
    telemetryService(settings.service),
    tracesUrl(new URL(settings.traces)),
    logsUrl(new URL(settings.logs)),
    consoleOutput(console),
  ],
});

await tools.ready;

await serveTelemetryWorker(tools.resolve(threadDrain));

const ended = await tools.close({ graceful: true });

// A throw ends this thread with an error event; the server's telemetryThread then stops failed.
if (ended.status === "failed") throw ended.error;
if (ended.teardownErrors?.length) throw ended.teardownErrors[0];

import { operation } from "@tinker/core";
import { z } from "zod";

export const greet = operation({
  label: "greet",
  input: z.object({ name: z.string().min(1) }),
  run: (_deps, { input }) => ({ text: `Hello, ${input.name}.` }),
});

import { createServerFn } from "@tanstack/react-start";

import { startRequests } from "~/components/requests";

import { greetRead } from "./greet.server";

export const runGreet = createServerFn({ method: "GET" })
  .middleware([startRequests.middleware])
  .handler(async ({ context }) => context.session.run(greetRead));

import { operation } from "@tinker/core";

import type { Errors } from "~/components/errors";
import { requestStop } from "~/components/requests";

import { greet } from "@/backend/greet";

/** The greeting, read for one request. A cancel raises Cancelled; a failure stays as is. */
export const greetRead = operation({
  label: "transport.greet",
  depends: { read: greet.controller, stop: requestStop.required },
  run: async ({ read, stop }, { raise: coreRaise }) => {
    const raise: Errors.Raise = coreRaise;

    const result = await read.settle({ input: { name: "world" }, signal: stop });

    if (result.status === "failed") throw result.error;
    if (result.status === "cancelled") return raise("Cancelled", {});
    return result.value;
  },
});

import { operation } from "@tinker/core";

import type { Errors } from "~/components/errors";
import { health } from "~/components/health";
